/bin/bash -lc "python - <<'PY'
from pathlib import Path
import json,re
q=Path('projects/holoen/research/qa'); r=json.loads((q/'registry.json').read_text()); m=json.loads((q/'manifest.json').read_text())
print('MANIFEST PACKETS',json.dumps(m['packets'],ensure_ascii=False));print('CREDITS',json.dumps(r['credits'],ensure_ascii=False))
print('CAST INVENTORY')
for c in r['cast']:print(c['name'],c['file'],'GROUPS:',c['groups'],'ALIASES:',c['other_names'])
print('WORLD INVENTORY')
for w in r['world']:print(w)
terms=r['reference_only']+['Kanata','Kanaken','KALAZ','Risu','Kobo','Zeta','Iofi','Reine','Korone','Fubuki','Mio','Polka','Nene','Pekora','Watame','Subaru','Flare','Rikka','Sana','Shion','Miko','Towa','Ao','Kanade','MVP','Moona','LYRA','Grindstone','Graondstone','KoMeHa','quote','alias','scope','roster','propagat','BR-']
patt=re.compile('|'.join(re.escape(t) for t in terms),re.I)
for p in sorted(q.glob('audit-*.md')):
 print('\\nAUDIT',p.name)
 for line in p.read_text().splitlines():
  if line.startswith('##') or (line.startswith('|') and patt.search(line)):print(line)
PY"

